select json_build_object(
 'id', l.id, 'tlid', l.tlid, 'county', l.county, 'jurisdiction', l.jurisdiction, 'zone_raw', l.zone_raw, 'zone', l.zone,
 'address', l.site_address, 'area_sqft', l.area_sqft, 'facts', l.facts, 'srid', ST_SRID(l.geom),
 'geom', ST_AsGeoJSON(l.geom)::json,
 'results', (select json_agg(json_build_object('design', r.design_key, 'tier', r.tier, 'slack_ft', r.slack_ft, 'binding', r.binding, 'checks', r.checks) order by r.design_key) from flats.lot_results r where r.lot_id=l.id and r.run_id=70),
 'flags', (select json_agg(json_build_object('design', f.design_key, 'code', f.code, 'sev', f.severity, 'colour', f.colour, 'status', f.status, 'source', f.source, 'low', f.bounds_low, 'high', f.bounds_high)) from flats.flag_instances f where f.tlid=l.tlid and f.county=l.county),
 'neighbours', (select json_agg(json_build_object('tlid', n.tlid, 'zone', n.zone, 'area', n.area_sqft, 'addr', n.site_address, 'geom', ST_AsGeoJSON(n.geom)::json)) from flats.lots n where n.snapshot_id=l.snapshot_id and n.id<>l.id and ST_DWithin(n.geom, l.geom, 120))
)
from flats.lots l where l.id in (21560368,21557548,21561372,21570296,21570469,21105108,21115029,21103957,21656378,21564157,21656737,21620873,21619594,21628910,21530161,21510224,21545273,21549328,21547040,21524784,21549336,21634558,21533451,21634216,21649199,21647927,21644410,21478362,21490880,21478594,21386683,21439321,21260486,21245513,21201095,21485151,21159741,21450746,21262121,21246767,21246921,21235559,21447956,21164207,21443804,21449003,21443208,21424525,21446659,21164630,21439717,21178907,21455366,21264240,21438710,21235432,21264318,21257338,21369490,21263328,21360939,21262352,21197815,21371018,21188551,21258112,21166586,21156412,21285405,21285102,21283913,21466232,21353517,21466230,21282218,21275692,21275615,21325064,21309562,21320804,21311110,21612605,21612520,21612588,21224455,21401640,21398464,21615111,21625714,21621649,21625708,21294106,21314986,21148709,21605795,21314460,21393077,21414177,21294532,21303902,21134341,21304496);
